async function seedAdmin() {
  const email = process.env.SEED_ADMIN_EMAIL || 'admin@nucleo.local'
  const password = process.env.SEED_ADMIN_PASSWORD || 'admin123'
  const client = await pool.connect()
  try {
    const org = await client.query('SELECT id FROM organizations ORDER BY created_at LIMIT 1')
    const role = await client.query("SELECT id FROM roles WHERE name='Administrador'")
    const hash = await bcrypt.hash(password, 12)
    const user = await client.query('INSERT INTO users (organization_id,name,email,password_hash) VALUES ($1,$2,$3,$4) ON CONFLICT(email) DO UPDATE SET password_hash=EXCLUDED.password_hash RETURNING id', [org.rows[0].id, 'Administrador local', email, hash])
    await client.query('INSERT INTO user_roles(user_id,role_id) VALUES($1,$2) ON CONFLICT DO NOTHING', [user.rows[0].id, role.rows[0].id])
  } finally { client.release() }
}

function auth(req, res, next) {
  try {
    const token = (req.headers.authorization || '').replace('Bearer ', '')
    if (!token) throw new Error('missing token')
    req.user = jwt.verify(token, secret)
    next()
  } catch { res.status(401).json({ error: 'Não autenticado' }) }
}
const requirePermission = code => async (req, res, next) => {
  const result = await pool.query('SELECT 1 FROM user_roles ur JOIN role_permissions rp ON rp.role_id=ur.role_id JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=$1 AND p.code=$2', [req.user.id, code])
  if (!result.rowCount) return res.status(403).json({ error: 'Permissão insuficiente', code })
  next()
}
const audit = async (client, req, action, entity, entityId, metadata = {}) => client.query('INSERT INTO audit_logs(organization_id,user_id,action,entity,entity_id,metadata) VALUES($1,$2,$3,$4,$5,$6)', [req.user.organizationId, req.user.id, action, entity, entityId || null, metadata])
const escapeMarkup = value => String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')
const interpolate = (template,values) => String(template||'').replace(/{{\s*([a-zA-Z0-9_]+)\s*}}/g,(_,key)=>escapeMarkup(values[key]||'-'))
const generatePdf = payload => new Promise((resolvePromise,reject)=>{
  const python=resolve(process.cwd(),'.venv/bin/python'),script=resolve(process.cwd(),'server/pdf/generate_document.py')
  const child=spawn(python,[script],{stdio:['pipe','pipe','pipe']});const chunks=[],errors=[]
  child.stdout.on('data',chunk=>chunks.push(chunk));child.stderr.on('data',chunk=>errors.push(chunk))
  child.on('error',reject);child.on('close',code=>code===0?resolvePromise(Buffer.concat(chunks)):reject(new Error(Buffer.concat(errors).toString()||`Falha ao gerar PDF (${code})`)))
  child.stdin.end(JSON.stringify(payload))
})
const integrationKey=createHash('sha256').update(process.env.INTEGRATION_ENCRYPTION_KEY||secret).digest()
const encryptSecret=value=>{if(!value)return null;const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',integrationKey,iv),encrypted=Buffer.concat([cipher.update(String(value),'utf8'),cipher.final()]),tag=cipher.getAuthTag();return Buffer.concat([iv,tag,encrypted]).toString('base64')}
const decryptSecret=value=>{if(!value)return '';const data=Buffer.from(value,'base64'),iv=data.subarray(0,12),tag=data.subarray(12,28),encrypted=data.subarray(28),decipher=createDecipheriv('aes-256-gcm',integrationKey,iv);decipher.setAuthTag(tag);return Buffer.concat([decipher.update(encrypted),decipher.final()]).toString('utf8')}
const hashToken=value=>createHash('sha256').update(String(value)).digest('hex')

