app.post('/api/catechesis/groups/:id/enrollments',auth,requirePermission('catechesis.enroll'),async(req,res)=>{const parsed=z.object({personId:z.string().uuid(),enrolledAt:z.string().min(10),sponsorName:z.string().optional(),notes:z.string().optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Selecione o catequizando e a data'});const x=parsed.data,client=await pool.connect();try{await client.query('BEGIN');const group=await client.query('SELECT * FROM catechesis_groups WHERE id=$1 AND organization_id=$2 AND active FOR UPDATE',[req.params.id,req.user.organizationId]);if(!group.rowCount)throw new Error('Grupo não encontrado');const count=await client.query("SELECT count(*)::int total FROM catechesis_enrollments WHERE group_id=$1 AND status='active'",[req.params.id]);if(group.rows[0].capacity&&count.rows[0].total>=group.rows[0].capacity)throw new Error('A turma atingiu a capacidade máxima');const person=await client.query('SELECT 1 FROM people WHERE id=$1 AND organization_id=$2',[x.personId,req.user.organizationId]);if(!person.rowCount)throw new Error('Catequizando não encontrado');const result=await client.query("INSERT INTO catechesis_enrollments(organization_id,group_id,person_id,status,enrolled_at,sponsor_name,notes) VALUES($1,$2,$3,'active',$4,$5,$6) ON CONFLICT(group_id,person_id) DO UPDATE SET status='active',enrolled_at=excluded.enrolled_at,sponsor_name=excluded.sponsor_name,notes=excluded.notes,updated_at=now() RETURNING *",[req.user.organizationId,req.params.id,x.personId,x.enrolledAt,x.sponsorName||null,x.notes||null]);await audit(client,req,'enroll','catechesis_enrollments',result.rows[0].id,{groupId:req.params.id});await client.query('COMMIT');res.status(201).json({data:result.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
app.post('/api/catechesis/groups/:id/sessions',auth,requirePermission('catechesis.sessions.create'),async(req,res)=>{const parsed=z.object({sessionDate:z.string().min(10),startsAt:z.string().optional(),endsAt:z.string().optional(),topic:z.string().min(2),sessionType:z.string().min(2).default('class'),catechist:z.string().optional(),notes:z.string().optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe data, tema e tipo do encontro'});const x=parsed.data;try{const result=await pool.query("INSERT INTO catechesis_sessions(organization_id,group_id,session_date,starts_at,ends_at,topic,session_type,catechist,notes) SELECT organization_id,id,$3,$4,$5,$6,$7,$8,$9 FROM catechesis_groups WHERE id=$1 AND organization_id=$2 RETURNING *",[req.params.id,req.user.organizationId,x.sessionDate,x.startsAt||null,x.endsAt||null,x.topic,x.sessionType,x.catechist||null,x.notes||null]);if(!result.rowCount)return res.status(404).json({error:'Grupo não encontrado'});await audit(pool,req,'create','catechesis_sessions',result.rows[0].id,{groupId:req.params.id});res.status(201).json({data:result.rows[0]})}catch(error){res.status(409).json({error:error.code==='23505'?'Já existe encontro neste horário':error.message})}})
app.put('/api/catechesis/sessions/:id/attendance',auth,requirePermission('catechesis.attendance.manage'),async(req,res)=>{const parsed=z.object({records:z.array(z.object({enrollmentId:z.string().uuid(),status:z.enum(['present','absent','justified']),notes:z.string().optional()})).min(1)}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe a frequência dos catequizandos'});const client=await pool.connect();try{await client.query('BEGIN');const session=await client.query('SELECT * FROM catechesis_sessions WHERE id=$1 AND organization_id=$2 FOR UPDATE',[req.params.id,req.user.organizationId]);if(!session.rowCount)throw new Error('Encontro não encontrado');for(const record of parsed.data.records){const valid=await client.query('SELECT 1 FROM catechesis_enrollments WHERE id=$1 AND group_id=$2 AND organization_id=$3',[record.enrollmentId,session.rows[0].group_id,req.user.organizationId]);if(!valid.rowCount)throw new Error('Matrícula inválida para este grupo');await client.query('INSERT INTO catechesis_attendance(organization_id,session_id,enrollment_id,status,notes) VALUES($1,$2,$3,$4,$5) ON CONFLICT(session_id,enrollment_id) DO UPDATE SET status=excluded.status,notes=excluded.notes,recorded_at=now()',[req.user.organizationId,req.params.id,record.enrollmentId,record.status,record.notes||null])}await client.query("UPDATE catechesis_sessions SET status='held' WHERE id=$1",[req.params.id]);await audit(client,req,'attendance','catechesis_sessions',req.params.id,{records:parsed.data.records.length});await client.query('COMMIT');res.json({updated:parsed.data.records.length})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
app.post('/api/catechesis/enrollments/:id/transfer',auth,requirePermission('catechesis.transfer'),async(req,res)=>{const parsed=z.object({toGroupId:z.string().uuid(),transferredOn:z.string().min(10),reason:z.string().optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe grupo de destino e data'});const x=parsed.data,client=await pool.connect();try{await client.query('BEGIN');const enrollment=await client.query("SELECT * FROM catechesis_enrollments WHERE id=$1 AND organization_id=$2 AND status='active' FOR UPDATE",[req.params.id,req.user.organizationId]);if(!enrollment.rowCount)throw new Error('Matrícula ativa não encontrada');if(enrollment.rows[0].group_id===x.toGroupId)throw new Error('O grupo de destino deve ser diferente');const target=await client.query('SELECT * FROM catechesis_groups WHERE id=$1 AND organization_id=$2 AND active FOR UPDATE',[x.toGroupId,req.user.organizationId]);if(!target.rowCount)throw new Error('Grupo de destino não encontrado');const existing=await client.query('SELECT id FROM catechesis_enrollments WHERE group_id=$1 AND person_id=$2',[x.toGroupId,enrollment.rows[0].person_id]);if(existing.rowCount)throw new Error('Catequizando já está no grupo de destino');const created=await client.query("INSERT INTO catechesis_enrollments(organization_id,group_id,person_id,status,enrolled_at,sponsor_name,notes) VALUES($1,$2,$3,'active',$4,$5,$6) RETURNING *",[req.user.organizationId,x.toGroupId,enrollment.rows[0].person_id,x.transferredOn,enrollment.rows[0].sponsor_name,enrollment.rows[0].notes]);await client.query("UPDATE catechesis_enrollments SET status='transferred',updated_at=now() WHERE id=$1",[req.params.id]);const transfer=await client.query('INSERT INTO catechesis_transfers(organization_id,enrollment_id,from_group_id,to_group_id,transferred_on,reason,created_by) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *',[req.user.organizationId,req.params.id,enrollment.rows[0].group_id,x.toGroupId,x.transferredOn,x.reason||null,req.user.id]);await audit(client,req,'transfer','catechesis_enrollments',req.params.id,{toGroupId:x.toGroupId,newEnrollmentId:created.rows[0].id});await client.query('COMMIT');res.status(201).json({data:transfer.rows[0],enrollment:created.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
