app.post('/api/catechesis/enrollments/:id/export-sacrament',auth,requirePermission('catechesis.export'),async(req,res)=>{const parsed=z.object({requestedOn:z.string().min(10),plannedDate:z.string().optional(),community:z.string().optional(),notes:z.string().optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe a data do pedido'});const x=parsed.data,client=await pool.connect();try{await client.query('BEGIN');const enrollment=await client.query("SELECT ce.*,cg.stage_id,cg.community group_community,cs.sacrament_type,p.name person_name FROM catechesis_enrollments ce JOIN catechesis_groups cg ON cg.id=ce.group_id LEFT JOIN catechesis_stages cs ON cs.id=cg.stage_id JOIN people p ON p.id=ce.person_id WHERE ce.id=$1 AND ce.organization_id=$2 AND ce.status='completed' FOR UPDATE OF ce",[req.params.id,req.user.organizationId]);if(!enrollment.rowCount)throw new Error('Conclua a etapa antes de exportar');const row=enrollment.rows[0];if(!row.sacrament_type)throw new Error('A etapa não possui sacramento de destino');if(row.sacramental_application_id){const existing=await client.query('SELECT * FROM sacramental_applications WHERE id=$1',[row.sacramental_application_id]);await client.query('COMMIT');return res.json({data:existing.rows[0],alreadyExported:true})}const protocol=`CAT-${Date.now().toString(36).toUpperCase()}-${randomBytes(2).toString('hex').toUpperCase()}`,application=await client.query("INSERT INTO sacramental_applications(organization_id,sacrament_type,person_id,protocol,requested_on,planned_date,community,status,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,'pending',$8,$9) RETURNING *",[req.user.organizationId,row.sacrament_type,row.person_id,protocol,x.requestedOn,x.plannedDate||null,x.community||row.group_community||null,x.notes||`Exportado da catequese: ${row.person_name}`,req.user.id]);await client.query("INSERT INTO sacramental_application_requirements(organization_id,application_id,requirement_id) SELECT $1,$2,id FROM sacramental_requirements WHERE organization_id=$1 AND sacrament_type=$3 AND active ON CONFLICT DO NOTHING",[req.user.organizationId,application.rows[0].id,row.sacrament_type]);await client.query('UPDATE catechesis_enrollments SET sacramental_application_id=$1,updated_at=now() WHERE id=$2',[application.rows[0].id,row.id]);await audit(client,req,'export_sacrament','catechesis_enrollments',row.id,{applicationId:application.rows[0].id,sacramentType:row.sacrament_type});await client.query('COMMIT');res.status(201).json({data:application.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
