const dataColumnLabel=dataLabel
async function managedMetadata(entity){if(dataMetadataCache.has(entity.key))return dataMetadataCache.get(entity.key);const columns=(await pool.query("SELECT column_name,data_type,udt_name,is_nullable,column_default,is_generated,is_identity FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position",[entity.table])).rows;if(!columns.length)throw new Error('Tabela gerenciada não encontrada');const foreign=(await pool.query("SELECT a.attname column_name,ft.relname foreign_table FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_class ft ON ft.oid=c.confrelid JOIN unnest(c.conkey) WITH ORDINALITY ck(attnum,ord) ON true JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=ck.attnum WHERE c.contype='f' AND t.relname=$1",[entity.table])).rows,foreignMap=new Map(foreign.map(row=>[row.column_name,row.foreign_table])),editable=columns.filter(column=>!protectedDataColumns.has(column.column_name)&&column.is_generated!=='ALWAYS'&&column.is_identity!=='YES').map(column=>({name:column.column_name,label:dataColumnLabel(column.column_name),dataType:column.data_type,udtName:column.udt_name,nullable:column.is_nullable==='YES',required:column.is_nullable==='NO'&&!column.column_default&&!Object.hasOwn(entity.fixed,column.column_name),foreignTable:foreignMap.get(column.column_name)||null}));const metadata={columns,editable};dataMetadataCache.set(entity.key,metadata);return metadata}
const normalizeManagedValue=(value,column)=>{if(value===''||value===undefined)return column.nullable?null:value;if(value===null)return null;if(column.dataType==='jsonb'||column.dataType==='json')return typeof value==='string'?JSON.parse(value):value;if(column.dataType==='ARRAY')return Array.isArray(value)?value:String(value).split(',').map(item=>item.trim()).filter(Boolean);if(column.dataType==='boolean')return value===true||value==='true'||value==='1';if(['smallint','integer','bigint','numeric','real','double precision'].includes(column.dataType))return Number(value);return value}
async function managedForeignOptions(column,organizationId){if(!column.foreignTable)return[];const table=column.foreignTable,available=(await pool.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=$1",[table])).rows.map(row=>row.column_name);if(!available.includes('id'))return[];const candidates=['name','title','code','email','document_number','protocol','number','description'].filter(name=>available.includes(name)),label=candidates.length?`concat_ws(' · ',${candidates.map(quoteIdentifier).join(',')})`:'id::text',scope=available.includes('organization_id')?' WHERE organization_id=$1':'';const result=await pool.query(`SELECT id,${label} label FROM ${quoteIdentifier(table)}${scope} ORDER BY label NULLS LAST LIMIT 500`,scope?[organizationId]:[]);return result.rows}
const managedWhere=(entity,startIndex=2)=>{const entries=Object.entries(entity.fixed),clauses=['organization_id=$1'],values=[];entries.forEach(([column,value],index)=>{clauses.push(`${quoteIdentifier(column)}=$${startIndex+index}`);values.push(value)});return{sql:clauses.join(' AND '),values}}

