app.post('/api/data-management/:entity',auth,requirePermission('data_management.create'),async(req,res)=>{const entity=managedEntities[req.params.entity];if(!entity||!entity.canCreate)return res.status(404).json({error:'Inclusão não permitida nesta entidade'});const parsed=z.object({values:z.record(z.string(),z.unknown())}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Dados inválidos'});const client=await pool.connect();try{const metadata=await managedMetadata(entity),allowed=new Map(metadata.editable.map(column=>[column.name,column])),provided=Object.fromEntries(Object.entries(parsed.data.values).filter(([,value])=>value!==''&&value!==undefined)),values={...provided,...entity.fixed,organization_id:req.user.organizationId},allColumns=new Map(metadata.columns.map(column=>[column.column_name,column]));if(allColumns.has('created_by'))values.created_by=req.user.id;const entries=Object.entries(values).filter(([name])=>name==='organization_id'||name==='created_by'||allowed.has(name));for(const column of metadata.editable.filter(column=>column.required))if(values[column.name]===undefined||values[column.name]==='')throw new Error(`${column.label} é obrigatório`);const names=entries.map(([name])=>name),params=entries.map(([name,value])=>normalizeManagedValue(value,allowed.get(name)||allColumns.get(name)));await client.query('BEGIN');const result=await client.query(`INSERT INTO ${quoteIdentifier(entity.table)}(${names.map(quoteIdentifier).join(',')}) VALUES(${params.map((_,index)=>`$${index+1}`).join(',')}) RETURNING *`,params);await audit(client,req,'create',entity.table,result.rows[0].id,{source:'data_management'});await client.query('COMMIT');res.status(201).json({data:result.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.code==='23505'?'Já existe um registro com estes dados':error.message})}finally{client.release()}})
