app.delete('/api/data-management/:entity/:id',auth,requirePermission('data_management.delete'),async(req,res)=>{const entity=managedEntities[req.params.entity];if(!entity)return res.status(404).json({error:'Entidade não autorizada'});if(entity.immutable)return res.status(409).json({error:'Este histórico é imutável e não pode ser excluído'});const client=await pool.connect();try{const metadata=await managedMetadata(entity),columnNames=new Set(metadata.columns.map(column=>column.column_name)),where=managedWhere(entity,3);await client.query('BEGIN');let result,mode;if(columnNames.has('deleted_at')){result=await client.query(`UPDATE ${quoteIdentifier(entity.table)} SET deleted_at=now() WHERE id=$1 AND ${where.sql.replace('$1','$2')} RETURNING id`,[req.params.id,req.user.organizationId,...where.values]);mode='archive'}else if(columnNames.has('active')){result=await client.query(`UPDATE ${quoteIdentifier(entity.table)} SET active=false WHERE id=$1 AND ${where.sql.replace('$1','$2')} RETURNING id`,[req.params.id,req.user.organizationId,...where.values]);mode='deactivate'}else if(columnNames.has('status')&&entity.cancelValue){const cancelWhere=managedWhere(entity,4);result=await client.query(`UPDATE ${quoteIdentifier(entity.table)} SET status=$1 WHERE id=$2 AND ${cancelWhere.sql.replace('$1','$3')} RETURNING id`,[entity.cancelValue,req.params.id,req.user.organizationId,...cancelWhere.values]);mode='cancel'}else{const existing=await client.query(`SELECT id FROM ${quoteIdentifier(entity.table)} WHERE id=$1 AND ${where.sql.replace('$1','$2')} FOR UPDATE`,[req.params.id,req.user.organizationId,...where.values]);if(!existing.rowCount)throw new Error('Registro não encontrado nesta área');await audit(client,req,'delete',entity.table,req.params.id,{source:'data_management',mode:'delete'});result=await client.query(`DELETE FROM ${quoteIdentifier(entity.table)} WHERE id=$1 RETURNING id`,[req.params.id]);mode='delete'}if(!result.rowCount)throw new Error('Registro não encontrado nesta área');if(mode!=='delete')await audit(client,req,mode,entity.table,req.params.id,{source:'data_management'});await client.query('COMMIT');res.json({deleted:true,mode})}catch(error){await client.query('ROLLBACK');const dependency=error.code==='23503'?'O registro possui vínculos. Exclua primeiro os registros dependentes ou use a inativação disponível.':error.message;res.status(409).json({error:dependency})}finally{client.release()}})

