const advanceOccurrence=(iso,recurrence,index)=>{const date=new Date(iso);if(recurrence==='daily')date.setUTCDate(date.getUTCDate()+index);if(recurrence==='weekly')date.setUTCDate(date.getUTCDate()+7*index);if(recurrence==='monthly')date.setUTCMonth(date.getUTCMonth()+index);return date.toISOString()}
