app.post('/api/agenda/courses/:id/enrollments',auth,requirePermission('courses.enroll'),async(req,res)=>{const parsed=z.object({personId:z.string().uuid(),notes:z.string().optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Selecione uma pessoa'});const client=await pool.connect();try{await client.query('BEGIN');const course=await client.query('SELECT * FROM pastoral_courses WHERE id=$1 AND organization_id=$2 FOR UPDATE',[req.params.id,req.user.organizationId]);if(!course.rowCount)throw new Error('Curso não encontrado');const count=await client.query("SELECT count(*)::int total FROM course_enrollments WHERE course_id=$1 AND status IN ('enrolled','completed')",[req.params.id]);const status=course.rows[0].capacity&&count.rows[0].total>=course.rows[0].capacity?'waitlist':'enrolled';const result=await client.query('INSERT INTO course_enrollments(organization_id,course_id,person_id,status,notes) VALUES($1,$2,$3,$4,$5) ON CONFLICT(course_id,person_id) DO UPDATE SET status=excluded.status,notes=excluded.notes RETURNING *',[req.user.organizationId,req.params.id,parsed.data.personId,status,parsed.data.notes||null]);await audit(client,req,'enroll','course_enrollments',result.rows[0].id,{courseId:req.params.id,status});await client.query('COMMIT');res.status(201).json({data:result.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
