app.post('/api/accounting/entries',auth,requirePermission('accounting.entries.create'),async(req,res)=>{const parsed=accountingEntrySchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe data, histórico e ao menos duas partidas'});const x=parsed.data,totalDebit=x.lines.reduce((s,l)=>s+l.debit,0),totalCredit=x.lines.reduce((s,l)=>s+l.credit,0);if(Math.round(totalDebit*100)!==Math.round(totalCredit*100)||totalDebit<=0)return res.status(400).json({error:'O lançamento deve possuir débitos e créditos de mesmo valor'});if(x.lines.some(line=>(line.debit>0)===(line.credit>0)))return res.status(400).json({error:'Cada partida deve informar somente débito ou crédito'});const client=await pool.connect();try{await client.query('BEGIN');if(x.status==='posted')await assertOpenPeriod(client,req.user.organizationId,x.entryDate);const accountIds=[...new Set(x.lines.map(line=>line.accountId))],accounts=await client.query('SELECT id FROM accounting_accounts WHERE organization_id=$1 AND active AND accepts_entries AND id=ANY($2::uuid[])',[req.user.organizationId,accountIds]);if(accounts.rowCount!==accountIds.length)throw new Error('Uma ou mais contas são inválidas ou não aceitam lançamentos');const entry=await client.query("INSERT INTO accounting_entries(organization_id,entry_date,document_number,memo,status,posted_by,posted_at,created_by) VALUES($1,$2,$3,$4,$5,$6,CASE WHEN $5='posted' THEN now() ELSE null END,$6) RETURNING *",[req.user.organizationId,x.entryDate,x.documentNumber||null,x.memo,x.status,x.status==='posted'?req.user.id:null]);for(const line of x.lines)await client.query('INSERT INTO accounting_entry_lines(organization_id,entry_id,account_id,cost_center_id,description,debit,credit) VALUES($1,$2,$3,$4,$5,$6,$7)',[req.user.organizationId,entry.rows[0].id,line.accountId,line.costCenterId||null,line.description||null,line.debit,line.credit]);await audit(client,req,'create','accounting_entries',entry.rows[0].id,{status:x.status,total:totalDebit});await client.query('COMMIT');res.status(201).json({data:entry.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
app.post('/api/accounting/entries/:id/post',auth,requirePermission('accounting.entries.post'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const entry=await client.query("SELECT * FROM accounting_entries WHERE id=$1 AND organization_id=$2 AND status='draft' FOR UPDATE",[req.params.id,req.user.organizationId]);if(!entry.rowCount)throw new Error('Lançamento não encontrado ou já contabilizado');const row=entry.rows[0],totals=await client.query('SELECT coalesce(sum(debit),0)::numeric debit,coalesce(sum(credit),0)::numeric credit FROM accounting_entry_lines WHERE entry_id=$1',[row.id]),total=totals.rows[0];if(Number(total.debit)<=0||Math.round(Number(total.debit)*100)!==Math.round(Number(total.credit)*100))throw new Error('Lançamento contábil não está balanceado');await assertOpenPeriod(client,req.user.organizationId,row.entry_date);const result=await client.query("UPDATE accounting_entries SET status='posted',posted_by=$1,posted_at=now() WHERE id=$2 RETURNING *",[req.user.id,row.id]);await audit(client,req,'post','accounting_entries',row.id,{total:total.debit});await client.query('COMMIT');res.json({data:result.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
app.post('/api/accounting/entries/:id/reverse',auth,requirePermission('accounting.entries.post'),async(req,res)=>{const parsed=z.object({entryDate:z.string().min(10),memo:z.string().optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe a data do estorno'});const client=await pool.connect();try{await client.query('BEGIN');await assertOpenPeriod(client,req.user.organizationId,parsed.data.entryDate);const original=await client.query("SELECT * FROM accounting_entries WHERE id=$1 AND organization_id=$2 AND status='posted' FOR UPDATE",[req.params.id,req.user.organizationId]);if(!original.rowCount)throw new Error('Lançamento não encontrado ou não contabilizado');const row=original.rows[0];const reversal=await client.query("INSERT INTO accounting_entries(organization_id,entry_date,document_number,memo,status,source,posted_by,posted_at,reversed_entry_id,created_by) VALUES($1,$2,$3,$4,'posted','reversal',$5,now(),$6,$5) RETURNING *",[req.user.organizationId,parsed.data.entryDate,row.document_number,parsed.data.memo||`Estorno: ${row.memo}`,req.user.id,row.id]);await client.query('INSERT INTO accounting_entry_lines(organization_id,entry_id,account_id,cost_center_id,description,debit,credit) SELECT organization_id,$1,account_id,cost_center_id,description,credit,debit FROM accounting_entry_lines WHERE entry_id=$2',[reversal.rows[0].id,row.id]);await client.query("UPDATE accounting_entries SET status='reversed' WHERE id=$1",[row.id]);await audit(client,req,'reverse','accounting_entries',row.id,{reversalId:reversal.rows[0].id});await client.query('COMMIT');res.status(201).json({data:reversal.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
app.get('/api/accounting/trial-balance',auth,requirePermission('accounting.view'),async(req,res)=>{const from=String(req.query.from||'2000-01-01'),to=String(req.query.to||'2100-12-31');const result=await pool.query("SELECT aa.id,aa.code,aa.name,aa.account_type,aa.nature,coalesce(sum(ael.debit) FILTER(WHERE ae.id IS NOT NULL),0)::numeric debit,coalesce(sum(ael.credit) FILTER(WHERE ae.id IS NOT NULL),0)::numeric credit,(CASE WHEN aa.nature='debit' THEN coalesce(sum(ael.debit-ael.credit) FILTER(WHERE ae.id IS NOT NULL),0) ELSE coalesce(sum(ael.credit-ael.debit) FILTER(WHERE ae.id IS NOT NULL),0) END)::numeric balance FROM accounting_accounts aa LEFT JOIN accounting_entry_lines ael ON ael.account_id=aa.id LEFT JOIN accounting_entries ae ON ae.id=ael.entry_id AND ae.status='posted' AND ae.entry_date BETWEEN $2::date AND $3::date WHERE aa.organization_id=$1 GROUP BY aa.id ORDER BY aa.code",[req.user.organizationId,from,to]);res.json({data:result.rows})})
