app.post('/api/accounting/exercises/:id/close',auth,requirePermission('accounting.exercises.manage'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const exercise=await client.query("SELECT * FROM accounting_exercises WHERE id=$1 AND organization_id=$2 AND status='open' FOR UPDATE",[req.params.id,req.user.organizationId]);if(!exercise.rowCount)throw new Error('Exercício não encontrado ou já encerrado');const x=exercise.rows[0],drafts=await client.query("SELECT count(*)::int count FROM accounting_entries WHERE organization_id=$1 AND status='draft' AND entry_date BETWEEN $2 AND $3",[req.user.organizationId,x.starts_on,x.ends_on]),opening=await client.query('SELECT coalesce(sum(debit),0)::numeric debit,coalesce(sum(credit),0)::numeric credit FROM accounting_opening_balances WHERE exercise_id=$1',[x.id]);if(drafts.rows[0].count)throw new Error('Existem lançamentos em rascunho no exercício');if(Number(opening.rows[0].debit)!==Number(opening.rows[0].credit))throw new Error('Os saldos de abertura não estão balanceados');const result=await client.query("UPDATE accounting_exercises SET status='closed',closed_at=now(),closed_by=$1 WHERE id=$2 RETURNING *",[req.user.id,x.id]);await audit(client,req,'close','accounting_exercises',x.id,{year:x.year});await client.query('COMMIT');res.json({data:result.rows[0]})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})
