app.post('/api/accounting/opening-balances',auth,requirePermission('accounting.exercises.manage'),async(req,res)=>{const parsed=z.object({exerciseId:z.string().uuid(),accountId:z.string().uuid(),debit:z.coerce.number().min(0).default(0),credit:z.coerce.number().min(0).default(0),notes:z.string().optional()}).safeParse(req.body);if(!parsed.success||(parsed.data.debit>0)===(parsed.data.credit>0))return res.status(400).json({error:'Informe apenas débito ou crédito no saldo de abertura'});const x=parsed.data,result=await pool.query("INSERT INTO accounting_opening_balances(organization_id,exercise_id,account_id,debit,credit,notes) SELECT $1,e.id,a.id,$4,$5,$6 FROM accounting_exercises e JOIN accounting_accounts a ON a.id=$3 AND a.organization_id=$1 WHERE e.id=$2 AND e.organization_id=$1 AND e.status='open' ON CONFLICT(exercise_id,account_id) DO UPDATE SET debit=excluded.debit,credit=excluded.credit,notes=excluded.notes RETURNING *",[req.user.organizationId,x.exerciseId,x.accountId,x.debit,x.credit,x.notes||null]);if(!result.rowCount)return res.status(409).json({error:'Exercício ou conta inválidos'});await audit(pool,req,'upsert','accounting_opening_balances',result.rows[0].id);res.status(201).json({data:result.rows[0]})})
