app.get('/api/accounting/statements/:type',auth,requirePermission('accounting.statements.view'),async(req,res)=>{const parsed=z.object({type:z.enum(['journal','general-ledger','cash-book','balance-sheet','income-statement','cash-flow','equity-changes']),from:z.string().min(10),to:z.string().min(10)}).safeParse({...req.query,type:req.params.type});if(!parsed.success||parsed.data.from>parsed.data.to)return res.status(400).json({error:'Demonstração e período inválidos'});const x=parsed.data,org=req.user.organizationId;let columns=[],rows=[],summary={}
  if(x.type==='journal'){columns=['Data','Documento','Histórico','Conta','Débito','Crédito'];rows=(await pool.query("SELECT ae.entry_date,ae.document_number,ae.memo,aa.code||' · '||aa.name account,ael.debit,ael.credit FROM accounting_entries ae JOIN accounting_entry_lines ael ON ael.entry_id=ae.id JOIN accounting_accounts aa ON aa.id=ael.account_id WHERE ae.organization_id=$1 AND ae.status='posted' AND ae.entry_date BETWEEN $2 AND $3 ORDER BY ae.entry_date,ae.created_at,aa.code",[org,x.from,x.to])).rows}
  if(x.type==='general-ledger'||x.type==='cash-book'){columns=['Conta','Data','Documento','Histórico','Débito','Crédito','Saldo'];const cash=x.type==='cash-book';const found=await pool.query("SELECT aa.code||' · '||aa.name account,ae.entry_date,ae.document_number,ae.memo,ael.debit,ael.credit,CASE WHEN aa.nature='debit' THEN sum(ael.debit-ael.credit) OVER(PARTITION BY aa.id ORDER BY ae.entry_date,ae.created_at,ael.id) ELSE sum(ael.credit-ael.debit) OVER(PARTITION BY aa.id ORDER BY ae.entry_date,ae.created_at,ael.id) END balance FROM accounting_entries ae JOIN accounting_entry_lines ael ON ael.entry_id=ae.id JOIN accounting_accounts aa ON aa.id=ael.account_id WHERE ae.organization_id=$1 AND ae.status='posted' AND ae.entry_date BETWEEN $2 AND $3 AND (NOT $4::boolean OR aa.account_type='asset' AND aa.code LIKE '1.1%') ORDER BY aa.code,ae.entry_date,ae.created_at",[org,x.from,x.to,cash]);rows=found.rows}
  if(['balance-sheet','income-statement','equity-changes'].includes(x.type)){const types=x.type==='balance-sheet'?['asset','liability','equity']:x.type==='income-statement'?['revenue','expense']:['equity'];columns=['Código','Conta','Grupo','Saldo inicial','Débitos','Créditos','Saldo final'];rows=(await pool.query("SELECT aa.code,aa.name,aa.account_type,coalesce(ob.debit-ob.credit,0)+coalesce(sum(ael.debit-ael.credit) FILTER(WHERE ae.entry_date<$2),0) opening,coalesce(sum(ael.debit) FILTER(WHERE ae.entry_date BETWEEN $2 AND $3),0) debit,coalesce(sum(ael.credit) FILTER(WHERE ae.entry_date BETWEEN $2 AND $3),0) credit,coalesce(ob.debit-ob.credit,0)+coalesce(sum(ael.debit-ael.credit) FILTER(WHERE ae.entry_date<=$3),0) closing FROM accounting_accounts aa LEFT JOIN accounting_entry_lines ael ON ael.account_id=aa.id LEFT JOIN accounting_entries ae ON ae.id=ael.entry_id AND ae.status='posted' LEFT JOIN (SELECT account_id,sum(debit) debit,sum(credit) credit FROM accounting_opening_balances ob JOIN accounting_exercises ex ON ex.id=ob.exercise_id WHERE ex.organization_id=$1 AND ex.starts_on<=$2 AND ex.ends_on>=$2 GROUP BY account_id) ob ON ob.account_id=aa.id WHERE aa.organization_id=$1 AND aa.account_type=ANY($4::text[]) GROUP BY aa.id,ob.debit,ob.credit ORDER BY aa.code",[org,x.from,x.to,types])).rows;const natural=row=>['liability','equity','revenue'].includes(row.account_type)?-Number(row.closing):Number(row.closing);summary=rows.reduce((s,row)=>({...s,[row.account_type]:(s[row.account_type]||0)+natural(row)}),{})}
  if(x.type==='cash-flow'){columns=['Data','Histórico','Entradas','Saídas','Variação'];rows=(await pool.query("SELECT ae.entry_date,ae.memo,sum(ael.debit)::numeric inflow,sum(ael.credit)::numeric outflow,sum(ael.debit-ael.credit)::numeric variation FROM accounting_entries ae JOIN accounting_entry_lines ael ON ael.entry_id=ae.id JOIN accounting_accounts aa ON aa.id=ael.account_id WHERE ae.organization_id=$1 AND ae.status='posted' AND ae.entry_date BETWEEN $2 AND $3 AND aa.account_type='asset' AND aa.code LIKE '1.1%' GROUP BY ae.id ORDER BY ae.entry_date,ae.created_at",[org,x.from,x.to])).rows;summary=rows.reduce((s,row)=>({inflow:s.inflow+Number(row.inflow),outflow:s.outflow+Number(row.outflow),variation:s.variation+Number(row.variation)}),{inflow:0,outflow:0,variation:0})}
  res.json({type:x.type,from:x.from,to:x.to,columns,data:rows,summary})})
app.post('/api/accounting/import-financial',auth,requirePermission('accounting.import'),async(req,res)=>{const parsed=z.object({from:z.string().min(10),to:z.string().min(10)}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe o período de integração'});const client=await pool.connect();try{await client.query('BEGIN');const accounts=await client.query("SELECT code,id FROM accounting_accounts WHERE organization_id=$1 AND code IN ('1.1.01','4.1.01','5.1.01')",[req.user.organizationId]),byCode=new Map(accounts.rows.map(row=>[row.code,row.id]));if(byCode.size!==3)throw new Error('Plano de contas padrão incompleto');const transactions=await client.query("SELECT ft.* FROM financial_transactions ft LEFT JOIN accounting_source_links asl ON asl.organization_id=ft.organization_id AND asl.source_entity='financial_transactions' AND asl.source_id=ft.id WHERE ft.organization_id=$1 AND ft.occurred_at BETWEEN $2::date AND $3::date AND ft.kind IN ('income','expense') AND asl.id IS NULL ORDER BY ft.occurred_at,ft.created_at FOR UPDATE OF ft",[req.user.organizationId,parsed.data.from,parsed.data.to]);let imported=0;for(const tx of transactions.rows){await assertOpenPeriod(client,req.user.organizationId,tx.occurred_at);const entry=await client.query("INSERT INTO accounting_entries(organization_id,entry_date,document_number,memo,status,source,posted_by,posted_at,created_by) VALUES($1,$2,$3,$4,'posted','financial',$5,now(),$5) RETURNING id",[req.user.organizationId,tx.occurred_at,tx.external_id,tx.description,req.user.id]);const cash=byCode.get('1.1.01'),counterpart=byCode.get(tx.kind==='income'?'4.1.01':'5.1.01'),lines=tx.kind==='income'?[[cash,tx.amount,0],[counterpart,0,tx.amount]]:[[counterpart,tx.amount,0],[cash,0,tx.amount]];for(const [accountId,debit,credit] of lines)await client.query('INSERT INTO accounting_entry_lines(organization_id,entry_id,account_id,description,debit,credit) VALUES($1,$2,$3,$4,$5,$6)',[req.user.organizationId,entry.rows[0].id,accountId,tx.description,debit,credit]);await client.query("INSERT INTO accounting_source_links(organization_id,source_entity,source_id,entry_id) VALUES($1,'financial_transactions',$2,$3)",[req.user.organizationId,tx.id,entry.rows[0].id]);imported++}await audit(client,req,'import','accounting_entries',null,{from:parsed.data.from,to:parsed.data.to,imported});await client.query('COMMIT');res.json({imported})}catch(error){await client.query('ROLLBACK');res.status(409).json({error:error.message})}finally{client.release()}})

const assetProjection=`SELECT a.*,ac.name category_name,al.name location_name,p.name custodian_name,
CASE WHEN a.depreciation_method='straight_line' AND a.acquisition_date IS NOT NULL AND a.useful_life_months>0 THEN least(a.useful_life_months,greatest(0,(extract(year from age($2::date,a.acquisition_date))*12+extract(month from age($2::date,a.acquisition_date)))::int)) ELSE 0 END elapsed_months,
CASE WHEN a.depreciation_method='straight_line' AND a.acquisition_date IS NOT NULL AND a.useful_life_months>0 THEN round(least(a.acquisition_value-a.residual_value,(a.acquisition_value-a.residual_value)/a.useful_life_months*least(a.useful_life_months,greatest(0,(extract(year from age($2::date,a.acquisition_date))*12+extract(month from age($2::date,a.acquisition_date)))::int))),2) ELSE 0 END accumulated_depreciation,
CASE WHEN a.depreciation_method='straight_line' AND a.acquisition_date IS NOT NULL AND a.useful_life_months>0 THEN a.acquisition_value-round(least(a.acquisition_value-a.residual_value,(a.acquisition_value-a.residual_value)/a.useful_life_months*least(a.useful_life_months,greatest(0,(extract(year from age($2::date,a.acquisition_date))*12+extract(month from age($2::date,a.acquisition_date)))::int))),2) ELSE a.acquisition_value END book_value
FROM assets a LEFT JOIN asset_categories ac ON ac.id=a.category_id LEFT JOIN asset_locations al ON al.id=a.location_id LEFT JOIN people p ON p.id=a.custodian_id WHERE a.organization_id=$1 ORDER BY a.name`
