app.get('/api/social/households',auth,requirePermission('social.view'),async(req,res)=>{const result=await pool.query("SELECT sh.*,p.name reference_person_name,coalesce(m.member_count,0)::int member_count,coalesce(a.open_count,0)::int open_assistance_count,coalesce(b.delivered_value,0)::numeric delivered_value FROM social_households sh LEFT JOIN people p ON p.id=sh.reference_person_id LEFT JOIN LATERAL (SELECT count(*) member_count FROM social_household_members WHERE household_id=sh.id) m ON true LEFT JOIN LATERAL (SELECT count(*) open_count FROM social_assistance_records WHERE household_id=sh.id AND status IN ('open','follow_up')) a ON true LEFT JOIN LATERAL (SELECT sum(estimated_value) delivered_value FROM social_benefit_deliveries WHERE household_id=sh.id) b ON true WHERE sh.organization_id=$1 ORDER BY CASE sh.vulnerability_level WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,sh.family_name",[req.user.organizationId]);res.json({data:result.rows})})
