app.post('/api/portal/credentials',auth,requirePermission('portal.credentials.manage'),async(req,res)=>{const parsed=z.object({personId:z.string().uuid(),credentialType:z.string().min(2),validFrom:z.string().datetime().optional(),validUntil:z.string().datetime().optional(),metadata:z.record(z.string(),z.unknown()).default({})}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe pessoa, tipo e validade'});const x=parsed.data,code=randomBytes(8).toString('hex').toUpperCase();const result=await pool.query('INSERT INTO portal_credentials(organization_id,person_id,credential_type,code,valid_from,valid_until,metadata,created_by) SELECT $1,id,$3,$4,coalesce($5,now()),$6,$7::jsonb,$8 FROM people WHERE id=$2 AND organization_id=$1 RETURNING *',[req.user.organizationId,x.personId,x.credentialType,code,x.validFrom||null,x.validUntil||null,JSON.stringify(x.metadata),req.user.id]);if(!result.rowCount)return res.status(404).json({error:'Pessoa não encontrada'});await audit(pool,req,'issue','portal_credentials',result.rows[0].id,{type:x.credentialType});res.status(201).json({data:result.rows[0]})})
