app.put('/api/sharing/config',auth,requirePermission('sharing.configure'),async(req,res)=>{const parsed=z.object({percentage:z.coerce.number().min(0).max(100),dueDay:z.coerce.number().int().min(1).max(28),beneficiary:z.string().optional(),instructions:z.string().optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Informe percentual e vencimento válidos'});const x=parsed.data;const result=await pool.query('INSERT INTO fraternal_sharing_configs(organization_id,percentage,due_day,beneficiary,instructions,updated_by) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(organization_id) DO UPDATE SET percentage=excluded.percentage,due_day=excluded.due_day,beneficiary=excluded.beneficiary,instructions=excluded.instructions,updated_by=excluded.updated_by,updated_at=now() RETURNING *',[req.user.organizationId,x.percentage,x.dueDay,x.beneficiary||null,x.instructions||null,req.user.id]);await audit(pool,req,'update','fraternal_sharing_configs',result.rows[0].id,{percentage:x.percentage});res.json({data:result.rows[0]})})
