app.post('/api/compliance/generate',auth,requirePermission('compliance.generate'),async(req,res)=>{
  const parsed=z.object({obligationType:z.enum(['efd_reinf','sped_ecd','sped_ecf','dirf_receipts','income_statement','other']),periodStart:z.string().min(10),periodEnd:z.string().min(10)}).safeParse(req.body);if(!parsed.success||parsed.data.periodStart>parsed.data.periodEnd)return res.status(400).json({error:'Obrigação e período inválidos'})
  const x=parsed.data,[entries,withholdings,documents,organization]=await Promise.all([pool.query("SELECT count(*)::int count,coalesce(sum(ael.debit),0)::numeric debit,coalesce(sum(ael.credit),0)::numeric credit FROM accounting_entries ae LEFT JOIN accounting_entry_lines ael ON ael.entry_id=ae.id WHERE ae.organization_id=$1 AND ae.status='posted' AND ae.entry_date BETWEEN $2 AND $3",[req.user.organizationId,x.periodStart,x.periodEnd]),pool.query('SELECT tax_type,count(*)::int count,coalesce(sum(amount),0)::numeric amount FROM tax_withholdings WHERE organization_id=$1 AND competence BETWEEN $2 AND $3 GROUP BY tax_type',[req.user.organizationId,x.periodStart,x.periodEnd]),pool.query("SELECT document_type,count(*)::int count,coalesce(sum(net_amount),0)::numeric amount FROM fiscal_documents WHERE organization_id=$1 AND status IN ('validated','approved') AND issued_on BETWEEN $2 AND $3 GROUP BY document_type",[req.user.organizationId,x.periodStart,x.periodEnd]),pool.query('SELECT id,name FROM organizations WHERE id=$1',[req.user.organizationId])]),errors=[]
  if(!organization.rowCount)errors.push('Organismo não encontrado');if(x.obligationType.startsWith('sped_')&&Number(entries.rows[0].debit)!==Number(entries.rows[0].credit))errors.push('Escrituração contábil não balanceada');if(x.obligationType==='efd_reinf'&&!withholdings.rowCount)errors.push('Nenhuma retenção no período')
  const payload={version:1,organization:organization.rows[0],period:{start:x.periodStart,end:x.periodEnd},accounting:entries.rows[0],withholdings:withholdings.rows,fiscalDocuments:documents.rows,generatedAt:new Date().toISOString()}
  const result=await pool.query("INSERT INTO compliance_submissions(organization_id,obligation_type,period_start,period_end,payload,validation_errors,status,generated_by) VALUES($1,$2,$3,$4,$5::jsonb,$6::jsonb,$7,$8) ON CONFLICT(organization_id,obligation_type,period_start,period_end) DO UPDATE SET payload=excluded.payload,validation_errors=excluded.validation_errors,status=excluded.status,generated_by=excluded.generated_by,generated_at=now(),protocol=null,submitted_at=null,accepted_at=null RETURNING *",[req.user.organizationId,x.obligationType,x.periodStart,x.periodEnd,JSON.stringify(payload),JSON.stringify(errors),errors.length?'draft':'ready',req.user.id]);await audit(pool,req,'generate','compliance_submissions',result.rows[0].id,{type:x.obligationType,errors:errors.length});res.status(201).json({data:result.rows[0]})
})
