app.get('/api/people-center/overview',auth,requirePermission('people.view'),async(req,res)=>{
  const org=req.user.organizationId
  const [communities,households,relationships,entities,memberships,attendances,terms,consents,requests,transfers,fields,values]=await Promise.all([
    pool.query('SELECT c.*,p.name coordinator_name FROM parish_communities c LEFT JOIN people p ON p.id=c.coordinator_person_id WHERE c.organization_id=$1 ORDER BY c.active DESC,c.name',[org]),
    pool.query("SELECT h.*,c.name community_name,coalesce(m.members,0)::int member_count,coalesce(m.responsibles,0)::int responsible_count FROM parish_households h LEFT JOIN parish_communities c ON c.id=h.community_id LEFT JOIN LATERAL(SELECT count(*) FILTER(WHERE left_on IS NULL) members,count(*) FILTER(WHERE left_on IS NULL AND is_responsible) responsibles FROM parish_household_members WHERE household_id=h.id)m ON true WHERE h.organization_id=$1 ORDER BY h.active DESC,h.name",[org]),
    pool.query('SELECT r.*,p.name person_name,rp.name related_person_name FROM person_relationships r JOIN people p ON p.id=r.person_id JOIN people rp ON rp.id=r.related_person_id WHERE r.organization_id=$1 ORDER BY r.created_at DESC',[org]),
    pool.query("SELECT e.*,c.name community_name,coalesce(m.members,0)::int member_count,coalesce(m.coordinators,0)::int coordinator_count FROM pastoral_entities e LEFT JOIN parish_communities c ON c.id=e.community_id LEFT JOIN LATERAL(SELECT count(*) FILTER(WHERE status='active') members,count(*) FILTER(WHERE status='active' AND is_coordinator) coordinators FROM pastoral_memberships WHERE entity_id=e.id)m ON true WHERE e.organization_id=$1 ORDER BY e.active DESC,e.entity_type,e.name",[org]),
    pool.query('SELECT m.*,e.name entity_name,p.name person_name FROM pastoral_memberships m JOIN pastoral_entities e ON e.id=m.entity_id JOIN people p ON p.id=m.person_id WHERE m.organization_id=$1 ORDER BY m.status,m.joined_on DESC',[org]),
    pool.query('SELECT a.*,p.name person_name,c.name community_name,u.name attendant_name FROM service_attendances a LEFT JOIN people p ON p.id=a.person_id LEFT JOIN parish_communities c ON c.id=a.community_id LEFT JOIN users u ON u.id=a.attended_by WHERE a.organization_id=$1 ORDER BY a.attended_at DESC LIMIT 300',[org]),
    pool.query('SELECT t.*,p.name person_name,e.name entity_name FROM volunteer_terms t JOIN people p ON p.id=t.person_id LEFT JOIN pastoral_entities e ON e.id=t.entity_id WHERE t.organization_id=$1 ORDER BY t.created_at DESC',[org]),
    pool.query('SELECT c.*,p.name person_name FROM lgpd_consents c JOIN people p ON p.id=c.person_id WHERE c.organization_id=$1 ORDER BY c.granted_at DESC',[org]),
    pool.query('SELECT r.*,p.name person_name,u.name handler_name FROM lgpd_requests r JOIN people p ON p.id=r.person_id LEFT JOIN users u ON u.id=r.handled_by WHERE r.organization_id=$1 ORDER BY r.requested_at DESC',[org]),
    pool.query('SELECT t.*,p.name person_name FROM person_transfers t JOIN people p ON p.id=t.person_id WHERE t.organization_id=$1 ORDER BY t.requested_on DESC,t.created_at DESC',[org]),
    pool.query('SELECT * FROM person_field_definitions WHERE organization_id=$1 ORDER BY active DESC,label',[org]),
    pool.query('SELECT v.*,d.label,d.field_key,p.name person_name FROM person_field_values v JOIN person_field_definitions d ON d.id=v.field_definition_id JOIN people p ON p.id=v.person_id WHERE v.organization_id=$1 ORDER BY p.name,d.label',[org])
  ])
  res.json({communities:communities.rows,households:households.rows,relationships:relationships.rows,entities:entities.rows,memberships:memberships.rows,attendances:attendances.rows,volunteerTerms:terms.rows,consents:consents.rows,lgpdRequests:requests.rows,transfers:transfers.rows,fieldDefinitions:fields.rows,fieldValues:values.rows})
})

